\set ON_ERROR_STOP on
begin;
create function pg_temp.doc_ok(value boolean) returns void language plpgsql as $$ begin if value is distinct from true then raise exception 'Document assertion failed';end if;end $$;
create function pg_temp.doc_denied(query text,expected text) returns void language plpgsql as $$ begin begin execute query;exception when others then if sqlstate=expected then return;end if;raise;end;raise exception 'Expected document denial';end $$;
